import Foundation

struct PortManagerFeatureStrings {
    let title: String
    let filter: String
    let openFormat: String
    let empty: String
    let emptyHint: String
    let listeningCaption: String
    let scopeNote: String
    let kill: String
    let forceKill: String
    let loadFailed: String
    let refresh: String
    let copyPort: String
    let copyAddress: String
    let openInBrowser: String
    let terminateFormat: String
    let terminateMessageFormat: String
    let hubDescription: String
    let allInterfaces: String
    let allInterfacesHelp: String
    let updatedFormat: String
    let rowActionsFormat: String
    let clearSearch: String
    let tagSystemProtected: String
    let tagIdentityUnavailable: String
    let helpSystemProtected: String
    let helpIdentityUnavailable: String
}

extension FeatureStrings {
    static func portManager(_ language: AppLanguage) -> PortManagerFeatureStrings {
        switch language {
        case .enUS: return .enUS
        case .ptBR: return .ptBR
        case .tr: return .tr
        case .ru: return .ru
        case .es: return .es
        case .sk: return .sk
        case .de: return .de
        case .fr: return .fr
        case .it: return .it
        case .ja: return .ja
        case .ko: return .ko
        case .uk: return .uk
        case .zhHans: return .zhHans
        case .zhTW: return .zhTW
        case .zhHK: return .zhHK
        }
    }
}

extension PortManagerFeatureStrings {
    func pidAddress(pid: Int32, address: String) -> String {
        "PID \(pid)  •  \(address)"
    }
}

